	@ParameterizedTest
	@MethodSource("specs")
	void resultLexicalFormIsCanonical(Spec spec) {
		Literal result = (Literal) spec.function().evaluate(VF, spec.argsArray());
		CoreDatatype datatype = result.getCoreDatatype();
		if (datatype == CoreDatatype.XSD.INTEGER) {
			assertThat(result.getLabel()).matches("-?(0|[1-9][0-9]*)");
		} else if (datatype == CoreDatatype.XSD.DOUBLE) {
			// pins current behaviour: rdf4j's ValueFactory writes doubles with Java's Double.toString ("1.0", not
			// the XSD canonical "1.0E0"); the extension functions inherit that from createLiteral(double).
			assertThat(result.getLabel()).isEqualTo(Double.toString(result.doubleValue()));
		} else if (datatype == CoreDatatype.XSD.BOOLEAN) {
			assertThat(result.getLabel()).isIn("true", "false");
		} else if (datatype == CoreDatatype.RDF.JSON) {
			assertThat(JsonSupport.parse(result.getLabel())).isInstanceOf(List.class);
		} else {
			assertThat(datatype).isIn(CoreDatatype.XSD.STRING, CoreDatatype.RDF.LANGSTRING);
		}
	}

	@ParameterizedTest
	@MethodSource("specs")
	void repeatedAndConcurrentEvaluationGiveIdenticalResults(Spec spec) {
		Value first = spec.function().evaluate(VF, spec.argsArray());
		assertThat(spec.function().evaluate(VF, spec.argsArray())).isEqualTo(first);
		List<Value> concurrent = IntStream.range(0, 256)
				.parallel()
				.mapToObj(n -> spec.function().evaluate(VF, spec.argsArray()))
				.toList();
		assertThat(concurrent).allSatisfy(value -> assertThat(value).isEqualTo(first));
	}

