	@Test
	void everyVocabularyConstantHasARegisteredFunctionAndASpec() throws IllegalAccessException {
		Set<String> specUris = new HashSet<>();
		specs().forEach(spec -> specUris.add(spec.function().getURI()));
		for (Class<?> vocabulary : List.of(STRF.class, TEXTF.class)) {
			for (Field field : vocabulary.getFields()) {
				if (field.getType() == IRI.class && Modifier.isStatic(field.getModifiers())) {
					String uri = ((IRI) field.get(null)).stringValue();
					assertThat(FunctionRegistry.getInstance().get(uri)).as(uri).isPresent();
					assertThat(specUris).as(uri).contains(uri);
				}
			}
		}
	}

	@Test
	void serviceFileListsEveryStringAndTextFunctionExactlyOnce() throws IOException {
		List<String> entries = serviceEntries();
		for (String entry : entries) {
			if (entry.contains(".function.string.ext.") || entry.contains(".function.text.")) {
				assertThat(entries.stream().filter(entry::equals).count()).as(entry).isEqualTo(1);
			}
		}
	}

	private static List<String> serviceEntries() throws IOException {
		List<String> entries = new ArrayList<>();
		Enumeration<URL> resources = StringFamilyContractTest.class.getClassLoader().getResources(SERVICE_FILE);
		while (resources.hasMoreElements()) {
			try (BufferedReader reader = new BufferedReader(
					new InputStreamReader(resources.nextElement().openStream(), StandardCharsets.UTF_8))) {
				String line;
				while ((line = reader.readLine()) != null) {
					String trimmed = line.trim();
					if (!trimmed.isEmpty() && !trimmed.startsWith("#")) {
						entries.add(trimmed);
					}
				}
			}
		}
		return entries;
	}
